Function Show-HTMLInstallationWelcome {
    [CmdletBinding()]
    param (
        [switch]$AllowDefer,
        [switch]$BlockExecution,
        [string]$CloseApps = '',
        # FIX: default changed from 0 to -1. -1 is now the sentinel meaning "the times-based
        # limit isn't being used at all". With the old default of 0, a deployment that only
        # wanted to use -DeferDeadline (and never passed -DeferTimes) was silently treated as
        # having 0 defers left on the very first run, since 0 - 1 = -1 < 0.
        [int32]$DeferTimes = -1,
        [int32]$DeferDays = 0,
        [string]$DeferDeadline = '',
        [bool]$MinimizeWindows = $true,
        [bool]$TopMost = $true,
        [string]$CustomHtmlFile = '',
        [int32]$FormWidth = 800,
        [int32]$FormHeight = 600,
        [string]$ButtonContinueText = '',
        [string]$ButtonDeferText = ''
    )

    begin {

        ## Get the name of this function and write header
        [string]${CmdletName} = $PSCmdlet.MyInvocation.MyCommand.Name
        Initialize-ADTFunction -Cmdlet $PSCmdlet -SessionState $ExecutionContext.SessionState

        $deployModeSilent = $adtSession.DeployModeSilent
        $deployModeNonInteractive = $adtSession.DeployModeNonInteractive
        $scriptParentPath = $adtSession.ScriptParentPath
        [bool]$Silent = $false
        [double]$RequiredDiskSpace = $VWG_FreeSpace
    }

    process {

        # -----------------------------
        ## If running in NonInteractive mode, force the processes to close silently
        # -----------------------------
        if ($deployModeNonInteractive) {
            $deployModeSilent = $true
            $Silent = $true
        }

        # -----------------------------
        ## Zero-Config MSI append executables to CloseApps
        # -----------------------------
        if ($adtSession.UseDefaultMsi) {
            if (-not [string]::IsNullOrWhiteSpace($defaultMsiExecutablesList)) {
                Write-ADTLogEntry -Message "Zero-Config MSI detected. Appending MSI executables to CloseApps list." -Severity 1 -Source $CmdletName
                $CloseApps = if ([string]::IsNullOrWhiteSpace($CloseApps)) {
                    $defaultMsiExecutablesList
                }
                else {
                    "$CloseApps,$defaultMsiExecutablesList"
                }
            }
        }

        # -----------------------------
        ## Check disk space
        # -----------------------------
        if ($adtSession.CheckDiskSpace -and $RequiredDiskSpace -ge 0) {

            Write-ADTLogEntry -Message "Evaluating disk space requirements." -Severity 1 -Source $CmdletName
            [double]$freeDiskSpace = Get-ADTFreeDiskSpace

            if ($freeDiskSpace -lt $RequiredDiskSpace) {
                Write-ADTLogEntry -Message "Insufficient disk space. Required [$RequiredDiskSpace MB], Available [$freeDiskSpace MB]" -Severity 3 -Source $CmdletName
                if (-not $Silent) {
                    Show-ADTInstallationPrompt -Message "Insufficient disk space. Required: $RequiredDiskSpace MB, Available: $freeDiskSpace MB" -ButtonRightText 'OK' -Icon 'Error'
                }
                Close-ADTSession -ExitCode (Get-ADTConfig).UI.DefaultExitCode
            }
            else {
                Write-ADTLogEntry -Message 'Successfully passed minimum disk space requirement check.' -Severity 1 -Source $CmdletName
            }
        }

        # -----------------------------
        ## Build CloseApps process objects (from the parameter may include apps that aren't running)
        # -----------------------------
        [psobject[]]$processObjects = @()

        if ($CloseApps) {
            foreach ($process in ($CloseApps -split ',' | Where-Object { $_ })) {
                if ($process -like '*=*') {
                    $split = $process -split '='
                    $processObjects += [pscustomobject]@{
                        ProcessName        = $split[0]
                        ProcessDescription = $split[1]
                    }
                }
                else {
                    $processObjects += [pscustomobject]@{
                        ProcessName        = $process
                        ProcessDescription = ''
                    }
                }
            }
        }

        # -----------------------------
        # FIX (proctoclose check): filter down to processes that are ACTUALLY running right now.
        # This is what should drive "is there anything to close / do we need to bother the user"
        # previously the code only looked at whether CloseApps was *specified*, not whether the
        # app was actually open.
        # -----------------------------
        [psobject[]]$runningProcessObjects = @()
        foreach ($proc in $processObjects) {
            if (Get-Process -Name $proc.ProcessName -ErrorAction SilentlyContinue) {
                $runningProcessObjects += $proc
            }
        }

        if ($processObjects.Count -gt 0) {
            Write-ADTLogEntry -Message "CloseApps specified [$($processObjects.Count)]; currently running [$($runningProcessObjects.Count)]." -Severity 1 -Source $CmdletName
        }

        # -----------------------------
        ## Deferral history
        # FIX: writes/reads directly to/from the registry (no separate helper functions kept
        # inline here so the file only exposes the two functions: Show-HTMLInstallationWelcome
        # and Show-HTMLWelcomePrompt). Storage location matches PSADT v3's layout:
        #     HKLM\SOFTWARE\PSAppDeployToolkit\DeferHistory\<InstallName>
        #         DeferTimesRemaining (String)
        #         DeferDeadline       (String, yyyy-MM-dd HH:mm:ss)
        # -----------------------------

        # Build the registry path for this application, once, up front.
        $deferRegRawName = $adtSession.InstallName
        if ([string]::IsNullOrWhiteSpace($deferRegRawName)) {
            $deferRegRawName = "$($adtSession.AppVendor)_$($adtSession.AppName)_$($adtSession.AppVersion)"
        }
        $deferRegSafeName = Remove-ADTInvalidFileNameChars -Name $deferRegRawName
        if ([string]::IsNullOrWhiteSpace($deferRegSafeName)) {
            $deferRegSafeName = 'DefaultApplication'
        }
        $deferHistoryRegPath = "HKEY_LOCAL_MACHINE\SOFTWARE\PSAppDeployToolkit\DeferHistory\$deferRegSafeName"

        $deferTimesRemaining = $DeferTimes
        [string]$deferDeadlineUniversal = ''

        # Whether each deferral mechanism is actually "in play" for this run. This distinction
        # matters: DeferTimes defaults to -1 (sentinel = "not using a times-based limit"), so a
        # caller relying purely on -DeferDeadline is not accidentally treated as exhausted.
        [bool]$usesTimesMechanism = $false
        [bool]$usesDeadlineMechanism = $false

        if ($AllowDefer -or ($runningProcessObjects.Count -gt 0)) {

            # ---------------- Read stored history ----------------
            $storedTimesRemaining = $null
            try {
                $timesRaw = Get-ADTRegistryKey -LiteralPath $deferHistoryRegPath -Name 'DeferTimesRemaining' -ErrorAction SilentlyContinue
                if (-not [string]::IsNullOrWhiteSpace($timesRaw)) {
                    $storedTimesRemaining = [int]$timesRaw
                }
            }
            catch {
                Write-ADTLogEntry -Message "No stored DeferTimesRemaining found at [$deferHistoryRegPath]." -Severity 1 -Source $CmdletName
            }

            $storedDeadline = $null
            try {
                $deadlineRaw = Get-ADTRegistryKey -LiteralPath $deferHistoryRegPath -Name 'DeferDeadline' -ErrorAction SilentlyContinue
                if (-not [string]::IsNullOrWhiteSpace($deadlineRaw)) {
                    $storedDeadline = $deadlineRaw
                }
            }
            catch {
                Write-ADTLogEntry -Message "No stored DeferDeadline found at [$deferHistoryRegPath]." -Severity 1 -Source $CmdletName
            }

            # ---------------- Times ----------------
            if ($null -ne $storedTimesRemaining) {
                $usesTimesMechanism = $true
                $deferTimesRemaining = $storedTimesRemaining - 1
            }
            elseif ($DeferTimes -ge 0) {
                $usesTimesMechanism = $true
                $deferTimesRemaining = $DeferTimes - 1
            }

            # ---------------- Deadline ----------------
            # Precedence: 1) stored deadline from history (so it doesn't move once set),
            # 2) explicit -DeferDeadline parameter, 3) computed from -DeferDays.
            if (-not [string]::IsNullOrWhiteSpace($storedDeadline)) {
                try {
                    $deferDeadlineUniversal = ([DateTime]::Parse($storedDeadline)).ToString('yyyy-MM-dd HH:mm:ss')
                    $usesDeadlineMechanism = $true
                }
                catch {
                    Write-ADTLogEntry -Message "Stored DeferDeadline '$storedDeadline' is invalid. Resetting." -Severity 2 -Source $CmdletName
                }
            }
            elseif (-not [string]::IsNullOrWhiteSpace($DeferDeadline)) {
                try {
                    $deferDeadlineUniversal = ([DateTime]::Parse($DeferDeadline)).ToString('yyyy-MM-dd HH:mm:ss')
                    $usesDeadlineMechanism = $true
                }
                catch {
                    Write-ADTLogEntry -Message "Provided DeferDeadline '$DeferDeadline' is invalid. Ignoring." -Severity 2 -Source $CmdletName
                }
            }
            elseif ($DeferDays -gt 0) {
                $deferDeadlineUniversal = (Get-Date).AddDays($DeferDays).ToString('yyyy-MM-dd HH:mm:ss')
                $usesDeadlineMechanism = $true
            }

            # ---------------- Expiry ----------------
            # FIX: each mechanism now blocks defer independently. Previously defer was only
            # disabled when BOTH times AND deadline were exhausted, so a run with DeferTimes = 0
            # but no deadline could still (in edge cases) leave defer enabled. Now: if DeferTimes
            # is in play and drops below 0, OR the deadline is in play and has passed, defer is
            # disabled either condition alone is enough.
            if ($usesTimesMechanism -and $deferTimesRemaining -lt 0) {
                Write-ADTLogEntry -Message "Defer times remaining exhausted [$deferTimesRemaining]. Disabling deferral." -Severity 2 -Source $CmdletName
                $AllowDefer = $false
            }

            if ($usesDeadlineMechanism) {
                try {
                    if ([DateTime]::Parse($deferDeadlineUniversal) -lt (Get-Date)) {
                        Write-ADTLogEntry -Message "Defer deadline [$deferDeadlineUniversal] has passed. Disabling deferral." -Severity 2 -Source $CmdletName
                        $AllowDefer = $false
                    }
                }
                catch {
                    Write-ADTLogEntry -Message "Could not evaluate defer deadline. Disabling deferral to be safe." -Severity 2 -Source $CmdletName
                    $AllowDefer = $false
                }
            }
        }

        # -----------------------------
        # FIX (direct install path): only show the welcome dialog if there is actually something
        # to close OR a genuine deferral option to offer. By this point $AllowDefer has already
        # been forced to $false above if defer is exhausted / expired, so this check is safe
        # e.g. DeferTimes = 0 with nothing running now correctly skips the dialog entirely and
        # proceeds straight to install, instead of popping up a "Continue"-only dialog.
        # -----------------------------
        [bool]$needsPrompt = ($runningProcessObjects.Count -gt 0) -or [bool]$AllowDefer

        # -----------------------------
        ## Prompt user
        # -----------------------------
        if (-not $deployModeSilent -and -not $Silent -and $needsPrompt) {

            $welcomeParams = @{
                AllowDefer         = [bool]$AllowDefer
                DeferTimes         = $deferTimesRemaining
                DeferDeadline      = $deferDeadlineUniversal
                CustomHtmlFile     = $CustomHtmlFile
                MinimizeWindows    = $MinimizeWindows
                TopMost            = $TopMost
                FormWidth          = $FormWidth
                FormHeight         = $FormHeight
                ButtonContinueText = $ButtonContinueText
                ButtonDeferText    = $ButtonDeferText
            }

            $promptResult = Show-HTMLWelcomePrompt @welcomeParams

            switch ($promptResult) {

                'Continue' {
                    Write-ADTLogEntry -Message "User selected continue." -Severity 1 -Source $CmdletName
                }

                'Defer' {
                    Write-ADTLogEntry -Message "User deferred installation." -Severity 2 -Source $CmdletName

                    # Only persist a times value if the times mechanism is actually in play for
                    # this deployment otherwise we'd write a meaningless 0/-1 into the registry
                    # for a deployment that's only ever used -DeferDeadline.
                    if ($usesTimesMechanism) {
                        # UInt32 cannot be negative  clamp to 0 minimum so history reflects exhausted
                        $timesToStore = if ($deferTimesRemaining -ge 0) { [uint32]$deferTimesRemaining } else { [uint32]0 }
                        Write-ADTLogEntry -Message "Set deferral history: [DeferTimesRemaining = $timesToStore] at [$deferHistoryRegPath]." -Severity 1 -Source $CmdletName
                        Set-ADTRegistryKey -LiteralPath $deferHistoryRegPath -Name 'DeferTimesRemaining' -Value $timesToStore.ToString() -Type String
                    }

                    if ($usesDeadlineMechanism -and -not [string]::IsNullOrWhiteSpace($deferDeadlineUniversal)) {
                        Write-ADTLogEntry -Message "Set deferral history: [DeferDeadline = $deferDeadlineUniversal] at [$deferHistoryRegPath]." -Severity 1 -Source $CmdletName
                        Set-ADTRegistryKey -LiteralPath $deferHistoryRegPath -Name 'DeferDeadline' -Value $deferDeadlineUniversal -Type String
                    }

                    Close-ADTSession -ExitCode (Get-ADTConfig).UI.DeferExitCode
                }

                'Timeout' {
                    Write-ADTLogEntry -Message "Welcome prompt timed out." -Severity 3 -Source $CmdletName
                    Close-ADTSession -ExitCode (Get-ADTConfig).UI.DefaultExitCode
                }

                'Close' {
                    Write-ADTLogEntry -Message "User requested application closure." -Severity 1 -Source $CmdletName
                    foreach ($proc in $processObjects) {
                        $running = Get-Process -Name $proc.ProcessName -ErrorAction SilentlyContinue
                        foreach ($r in $running) {
                            try {
                                Write-ADTLogEntry -Message "Stopping process [$($r.ProcessName)]" -Severity 1 -Source $CmdletName
                                Stop-Process -Id $r.Id -Force -ErrorAction SilentlyContinue
                            }
                            catch {
                                Write-ADTLogEntry -Message "Failed to stop [$($r.ProcessName)]" -Severity 3 -Source $CmdletName
                            }
                        }
                    }
                }
            }
        }
        elseif (-not $needsPrompt) {
            Write-ADTLogEntry -Message "No applications are running and no valid deferral to offer. Proceeding directly with installation." -Severity 1 -Source $CmdletName
        }

        # -----------------------------
        ## Silent mode force close
        # -----------------------------
        if (($deployModeSilent -or $Silent) -and $processObjects) {
            Write-ADTLogEntry -Message "Silent mode - force closing applications." -Severity 1 -Source $CmdletName
            foreach ($proc in $processObjects) {
                Get-Process -Name $proc.ProcessName -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
            }
        }

        # -----------------------------
        ## Block execution if requested
        # -----------------------------
        if ($BlockExecution -and $processObjects) {
            Write-ADTLogEntry -Message "Blocking execution for processes." -Severity 1 -Source $CmdletName
            Set-Variable -Name 'BlockExecution' -Value $true -Scope Script
            Block-ADTAppExecution -ProcessName ($processObjects.ProcessName)
        }
    }

    end {
        Complete-ADTFunction -Cmdlet $PSCmdlet
    }
}

Function Show-HTMLWelcomePrompt {

    [CmdletBinding()]
    Param (
        [bool]$PersistPrompt = $false,
        [switch]$AllowDefer,
        [int]$DeferTimes,
        [String]$DeferDeadline = '',
        [bool]$MinimizeWindows = $true,
        [bool]$TopMost = $true,
        [switch]$CustomText = $false,
        [string]$CustomHtmlFile,
        [int32]$FormWidth = 800,
        [int32]$FormHeight = 600,
        [string]$buttonDeferText = '',
        [string]$buttonContinueText = ''
    )

    Begin {

        ## Get the name of this function and write header
        [string]${CmdletName} = $PSCmdlet.MyInvocation.MyCommand.Name
        Initialize-ADTFunction -Cmdlet $PSCmdlet -SessionState $ExecutionContext.SessionState

        $scriptParentPath = $adtSession.ScriptParentPath
        $script:welcomeTimer = $null
    }

    Process {
        ## Reset switches
        [bool]$showCloseApps = $false
        [bool]$showDefer = $false
        [bool]$persistWindow = $false

        ## Reset times
        [datetime]$startTime = Get-Date
        [datetime]$countdownTime = $startTime

        $pageUrl = $null
        $TMPCustomHtmlFile = $null

        if (-not (Get-Variable -Name 'configClosePromptButtonContinue' -Scope Script -ErrorAction SilentlyContinue)) {
            $configClosePromptButtonContinue = 'Continue'
        }

        if (-not (Get-Variable -Name 'configClosePromptButtonDefer' -Scope Script -ErrorAction SilentlyContinue)) {
            $configClosePromptButtonDefer = 'Defer'
        }

        if (-not (Get-Variable -Name 'configInstallationPersistInterval' -Scope Script -ErrorAction SilentlyContinue)) {
            $configInstallationPersistInterval = 30
        }

        if (-not (Get-Variable -Name 'configInstallationUITimeout' -Scope Script -ErrorAction SilentlyContinue)) {
            $configInstallationUITimeout = 3600
        }

        # ------------------------------------------------------------
        # Defer logic
        # ------------------------------------------------------------
        if ($AllowDefer -and (($DeferTimes -ge 0) -or $DeferDeadline)) {

            Write-ADTLogEntry -Message "User has the option to defer." -Severity 1 -Source $CmdletName

            $showDefer = $true

            if ($DeferDeadline) {

                if ($DeferDeadline -is [String]) {
                    $DeferDeadline = $DeferDeadline.Trim()
                }
            }
        }

        # ------------------------------------------------------------
        # Persist window logic
        # ------------------------------------------------------------
        if ($showDefer -and $PersistPrompt) {
            $persistWindow = $true
        }

        # ------------------------------------------------------------
        # WinForms initialization
        # ------------------------------------------------------------
        Add-Type -AssemblyName System.Windows.Forms
        Add-Type -AssemblyName System.Drawing

        [System.Windows.Forms.Application]::EnableVisualStyles()

        $formWelcome = New-Object System.Windows.Forms.Form
        $buttonContinue = New-Object System.Windows.Forms.Button
        $buttonDefer = New-Object System.Windows.Forms.Button
        $buttonAbort = New-Object System.Windows.Forms.Button

        $flowLayoutPanel = New-Object System.Windows.Forms.FlowLayoutPanel
        $panelButtons = New-Object System.Windows.Forms.Panel

        ## ------------------------------------------------------------
        ## Remove all event handlers from the controls
        ## ------------------------------------------------------------

        # Continue button handler
        $buttonContinue_OnClick = {
            $formWelcome.DialogResult = [System.Windows.Forms.DialogResult]::OK
            $formWelcome.Close()
        }

        # Defer button handler
        $buttonDefer_OnClick = {
            $formWelcome.DialogResult = [System.Windows.Forms.DialogResult]::No
            $formWelcome.Close()
        }

        # Abort/Timeout handler
        $buttonAbort_OnClick = {
            $formWelcome.DialogResult = [System.Windows.Forms.DialogResult]::Abort
            $formWelcome.Close()
        }

        [scriptblock]$Form_Cleanup_FormClosed = {

            try {
                if ($buttonContinue) { $buttonContinue.remove_Click($buttonContinue_OnClick) }
                if ($buttonDefer)    { $buttonDefer.remove_Click($buttonDefer_OnClick) }
                if ($buttonAbort)    { $buttonAbort.remove_Click($buttonAbort_OnClick) }

                if ($script:welcomeTimer) { $script:welcomeTimer.remove_Tick($timer_Tick) }
                if ($timerPersist) { $timerPersist.remove_Tick($timerPersist_Tick) }

                if ($formWelcome) {
                    $formWelcome.remove_Load($Form_StateCorrection_Load)
                    $formWelcome.remove_FormClosed($Form_Cleanup_FormClosed)
                }
            }
            catch {
            }
        }

        ## ------------------------------------------------------------
        ## Form state correction
        ## ------------------------------------------------------------
        [scriptblock]$Form_StateCorrection_Load = {
            ## Correct the initial state of the form to prevent the .NET maximized form issue
            $formWelcome.WindowState = 'Normal'
            $formWelcome.AutoSize = $true
            $formWelcome.TopMost = $TopMost
            $formWelcome.BringToFront()

            #  Get the start position of the form so we can return the form to this position if PersistPrompt is enabled
            Set-Variable -Name 'formWelcomeStartPosition' -Value $formWelcome.Location -Scope Script

            ## Initialize the countdown timer
            [datetime]$currentTime = Get-Date
            $script:welcomeTimer.Start()
        }

        ## ------------------------------------------------------------
        ## HTML preparation
        ## ------------------------------------------------------------
        if ($CustomHtmlFile) {

            $sourceFile = "$($adtSession.dirSupportFiles)\$CustomHtmlFile"

            if (Test-Path $sourceFile) {

                $TMPCustomHtmlFile = "~$CustomHtmlFile"
                $tmpPath = "$($adtSession.dirSupportFiles)\$TMPCustomHtmlFile"

                Copy-ADTFile -Path $sourceFile -Destination $tmpPath

                # Hide file
                (Get-Item $tmpPath -Force).Attributes = 'Hidden'

                $pageUrl = $tmpPath
            }
            else {
                Write-ADTLogEntry -Message "Cannot find HTML file: $sourceFile" -Severity 3 -Source $CmdletName
            }

            ## --------------------------------------------------------
            ## SINGLE-PASS HTML REPLACEMENT
            ## --------------------------------------------------------
            if ($pageUrl -and (Test-Path $pageUrl)) {

                $html = Get-Content -Path $pageUrl -Raw

                # Defer Deadline replacement in HTML
                if ($html -match "{DeferDeadline}" -and -not [string]::IsNullOrWhiteSpace($DeferDeadline)) {
                    try {
                        $deadlineFormatted = (Get-Date $DeferDeadline -Format "yyyy-MM-dd")
                        $html = $html -replace "{DeferDeadline}", $deadlineFormatted
                    }
                    catch {
                        $html = $html -replace "{DeferDeadline}", $DeferDeadline
                    }
                }

                # Defer Days replacement in HTML
                if ($html -match "{DeferDays}" -and -not [string]::IsNullOrWhiteSpace($DeferDeadline)) {
                    try {
                        $days = (New-TimeSpan -Start (Get-Date) -End (Get-Date $DeferDeadline)).Days
                        $html = $html -replace "{DeferDays}", $days
                    }
                    catch {
                        $html = $html -replace "{DeferDays}", '0'
                    }
                }

                Set-Content -Path $pageUrl -Value $html -Encoding UTF8
            }
        }

        ## ------------------------------------------------------------
        ## Main timer
        ## ------------------------------------------------------------
        if (-not $script:welcomeTimer) {
            $script:welcomeTimer = New-Object System.Windows.Forms.Timer
        }

        if (-not (Get-Variable -Name configInstallationUITimeout -ErrorAction SilentlyContinue)) {
            $configInstallationUITimeout = 3600
        }
        $script:welcomeTimer.Interval = ($configInstallationUITimeout * 1000)

        $timer_Tick = {
            $buttonAbort.PerformClick()
        }

        $script:welcomeTimer.add_Tick($timer_Tick)

        ## ------------------------------------------------------------
        ## Persistence timer
        ## ------------------------------------------------------------
        if ($persistWindow) {

            $timerPersist = New-Object System.Windows.Forms.Timer
            $timerPersist.Interval = ($configInstallationPersistInterval * 1000)

            $timerPersist_Tick = {
                #replacement for Update-InstallationWelcome dependency
                if ($formWelcome) {
                    $formWelcome.BringToFront()
                    $formWelcome.Refresh()
                }
            }

            $timerPersist.add_Tick($timerPersist_Tick)
            $timerPersist.Start()
        }

        ## ------------------------------------------------------------
        ## Form setup
        ## ------------------------------------------------------------

        $formWelcome.Controls.Add($buttonAbort)

        [System.Windows.Forms.Application]::EnableVisualStyles()

        # ------------------------------------------------------------
        # size handling
        # ------------------------------------------------------------
        if ($FormWidth -lt 600)  { $FormWidth = 600 }
        if ($FormHeight -lt 600) { $FormHeight = 600 }

        $System_Drawing_Size = New-Object System.Drawing.Size($FormWidth, $FormHeight)

        # ------------------------------------------------------------
        # Form properties
        # ------------------------------------------------------------
        $formWelcome.Font = [System.Drawing.SystemFonts]::DefaultFont
        $formWelcome.Size = $System_Drawing_Size
        $formWelcome.Padding = New-Object System.Windows.Forms.Padding(0)
        $formWelcome.Margin = New-Object System.Windows.Forms.Padding(0)
        $formWelcome.DataBindings.DefaultDataSourceUpdateMode = 0
        $formWelcome.Name = 'WelcomeForm'
        $formWelcome.Text = $installTitle
        if (Get-Variable -Name AppDeployLogoIcon -Scope Script -ErrorAction SilentlyContinue) {
            $formWelcome.Icon = New-Object System.Drawing.Icon($script:AppDeployLogoIcon)
        }
        $formWelcome.StartPosition = 'CenterScreen'
        $formWelcome.FormBorderStyle = 'FixedDialog'
        $formWelcome.MaximizeBox = $false
        $formWelcome.MinimizeBox = $false
        $formWelcome.WindowState = 'Normal'
        $formWelcome.TopMost = $true
        $formWelcome.TopLevel = $true

        # ------------------------------------------------------------
        # HTML browser
        # ------------------------------------------------------------
        $browserCtrl = New-Object System.Windows.Forms.WebBrowser
        $browserCtrl.IsWebBrowserContextMenuEnabled = $false
        $browserCtrl.ScriptErrorsSuppressed = $true
        $browserCtrl.Width = $FormWidth
        $browserCtrl.Height = $FormHeight - 120
        $browserCtrl.Location = New-Object System.Drawing.Point(0,0)
        $browserCtrl.Anchor = 'Left,Top,Bottom,Right'

        if ($pageUrl) {
            $browserCtrl.Navigate($pageUrl)
        }

        $formWelcome.Controls.Add($browserCtrl)

        # ------------------------------------------------------------
        # Flow panel positioning
        # ------------------------------------------------------------
        $flowLayoutPanel.Location = New-Object System.Drawing.Point(-40, ($FormHeight - 90))
        $flowLayoutPanel.Width = $FormWidth + 20
        $flowLayoutPanel.Height = 100
        $flowLayoutPanel.Anchor = 'Left,Bottom,Right'
        $flowLayoutPanel.Padding = 5
        $flowLayoutPanel.FlowDirection = 'RightToLeft'

        # ------------------------------------------------------------
        # Continue button
        # ------------------------------------------------------------
        $buttonContinue.DataBindings.DefaultDataSourceUpdateMode = 0

        $buttonContinue.Text = if ([string]::IsNullOrWhiteSpace($buttonContinueText)) {
            $configClosePromptButtonContinue
        } else {
            $buttonContinueText
        }

        $buttonContinue.Font = 'Segoe UI, 11pt'
        $buttonContinue.AutoSize = $true
        $buttonContinue.DialogResult = 'OK'

        $buttonContinue.add_Click($buttonContinue_OnClick)

        $flowLayoutPanel.Controls.Add($buttonContinue)

        # ------------------------------------------------------------
        # Defer button FIX: only add it to the form when defer is actually being offered.
        # Previously the button was always added (just governed by whether AllowDefer was
        # truthy at the top), which is harmless visually since $showDefer already gates the
        # earlier log message, but we now gate the actual control add on $showDefer too so a
        # "Continue only" dialog never shows a dead Defer button.
        # ------------------------------------------------------------
        if ($showDefer) {
            $buttonDefer.DataBindings.DefaultDataSourceUpdateMode = 0

            $buttonDefer.Text = if ([string]::IsNullOrWhiteSpace($buttonDeferText)) {
                $configClosePromptButtonDefer
            } else {
                $buttonDeferText
            }

            $buttonDefer.Font = 'Segoe UI, 11pt'
            $buttonDefer.AutoSize = $true
            $buttonDefer.DialogResult = 'No'
            $buttonDefer.add_Click($buttonDefer_OnClick)

            $flowLayoutPanel.Controls.Add($buttonDefer)
        }

        # ------------------------------------------------------------
        # Abort button (hidden)
        # ------------------------------------------------------------
        $buttonAbort.DataBindings.DefaultDataSourceUpdateMode = 0
        $buttonAbort.Name = 'buttonAbort'
        $buttonAbort.Size = New-Object System.Drawing.Size(1,1)
        $buttonAbort.TabStop = $false
        $buttonAbort.DialogResult = 'Abort'
        $buttonAbort.TabIndex = 5
        $buttonAbort.UseVisualStyleBackColor = $true
        $buttonAbort.add_Click($buttonAbort_OnClick)

        # ------------------------------------------------------------
        ## Add the Buttons Panel to the form
        # ------------------------------------------------------------
        $formWelcome.Controls.Add($flowLayoutPanel)

        # ------------------------------------------------------------
        ## Save the initial state of the form
        #  Init the OnLoad event to correct the initial state of the form
        #  Clean up the control events
        # ------------------------------------------------------------
        $formWelcomeWindowState = $formWelcome.WindowState
        $formWelcome.add_Load($Form_StateCorrection_Load)
        $formWelcome.add_FormClosed($Form_Cleanup_FormClosed)

        # ------------------------------------------------------------
        # Update function
        # ------------------------------------------------------------
        Function Update-InstallationWelcome {
            $formWelcome.BringToFront()
            $formWelcome.Location = New-Object System.Drawing.Point(
                $formWelcomeStartPosition.X,
                $formWelcomeStartPosition.Y
            )
            $formWelcome.Refresh()
        }

        # ------------------------------------------------------------
        ## Minimize all other windows
        # ------------------------------------------------------------

        if ($MinimizeWindows) {
            $shellApp = New-Object -ComObject Shell.Application
            $shellApp.MinimizeAll()
        }

        # ------------------------------------------------------------
        # Show form
        # ------------------------------------------------------------
        $result = $formWelcome.ShowDialog()
        $formWelcome.Dispose()

        # ------------------------------------------------------------
        # Result mapping
        # ------------------------------------------------------------
        switch ($result) {
            'OK'    { $result = 'Continue' }
            'No'    { $result = 'Defer' }
            'Yes'   { $result = 'Close' }
            'Abort' { $result = 'Timeout' }
        }

        # ------------------------------------------------------------
        # Cleanup temp HTML
        # ------------------------------------------------------------
        if ($TMPCustomHtmlFile)
        {
            $tmpPath = "$($adtSession.dirSupportFiles)\$TMPCustomHtmlFile"
            if (Test-Path $tmpPath) {
                Remove-Item -Path $tmpPath -Force -ErrorAction SilentlyContinue
            }
        }

        # ------------------------------------------------------------
        # Output
        # ------------------------------------------------------------
        Write-Output -InputObject $result
    }
    end {
        Complete-ADTFunction -Cmdlet $PSCmdlet
    }
}
